package com.tracker.controller;
import com.tracker.entity.*; import com.tracker.exception.ApiException; import com.tracker.repository.StudentAchievementRepository; import com.tracker.service.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/achievements") public class AchievementController {private final AccessService access;private final AchievementService service;private final StudentAchievementRepository awards;public AchievementController(AccessService a,AchievementService s,StudentAchievementRepository r){access=a;service=s;awards=r;}
 @PostMapping("/reconcile") public Map<String,Object> reconcile(Authentication a){User u=access.current(a);if(u.getRole()!=Role.STUDENT)throw new ApiException("Student access required",HttpStatus.FORBIDDEN);var rows=service.reconcile(u);return Map.of("points",awards.sumPointsByUserId(u.getId()),"items",rows);}
 @GetMapping public Map<String,Object> list(Authentication a){User u=access.current(a);if(u.getRole()!=Role.STUDENT)throw new ApiException("Student access required",HttpStatus.FORBIDDEN);var rows=awards.findByUserIdOrderByAwardedAtDesc(u.getId());return Map.of("points",awards.sumPointsByUserId(u.getId()),"items",rows);}}
